export function eligible(age) {
  if (!Number.isInteger(age)) return false;
  return age >= 18 && age <= 65;
}

export function accepted(quantity) {
  if (!Number.isInteger(Number(quantity))) return false;
  return quantity >= 1 && quantity < 10;
}

